export function buildCases(input){const edit=fn=>{const d=structuredClone(input);fn(...d.body);return d;},all=(...nodes)=>nodes;
 const positives=[['original independent supplied fields',structuredClone(input)],['empty supplied schedules',edit((...nodes)=>nodes.forEach(n=>{n.teams=[];n.games=[];}))],['unknown start, score and outcome',edit((...nodes)=>nodes.forEach(n=>n.games.forEach(g=>{g.startsAt=null;g.homeScore=null;g.awayScore=null;g.outcome='unknown';})))],['true zero and tied result without inference',edit((...nodes)=>nodes.forEach(n=>n.games.forEach(g=>{g.homeScore=0;g.awayScore=0;g.outcome='home-win';})))],['literal team and context text',edit((n,s,f)=>{n.teams[0].label='<script>literal team</script>';s.games[0].events[0].player='<img src=untrusted>';f.games[0].note='<svg onload=untrusted>';})],['independent game-local event IDs',edit((n,s,f)=>{n.games[1].periods[0].id=n.games[0].periods[0].id;s.games[1].events[0].id=s.games[0].events[0].id;f.games[1].events[0].id=f.games[0].events[0].id;})],['safe finite source links',edit((...nodes)=>nodes.forEach(n=>{n.source={label:'Synthetic source',url:'https://example.org/supplied-games'};n.games[0].source={label:'Synthetic game',url:'https://example.org/game'};}))],['supplied maximum counts and overtime numbering',edit((n,s,f)=>{n.games[0].homeScore=1000000;n.games[0].leaders[0].points=1000000;s.games[0].aggregate.home=1000000;f.games[0].events[0].points=1000000;f.games[0].periods[1].number=20;})]];
 const sem=(name,fn,code,path)=>[name,edit(fn),code,path],schema=(name,fn)=>[name,edit(fn),'SCHEMA'];
 const negatives=[
 sem('invalid supplied timezone',n=>n.timezone='Not/A_Zone','TIMEZONE','/body/0/timezone'),sem('duplicate team ID',n=>n.teams[1].id='all','DUPLICATE_ID','/body/0/teams/1/id'),sem('duplicate game ID',n=>n.games[1].id=n.games[0].id,'DUPLICATE_ID','/body/0/games/1/id'),sem('missing home team',n=>n.games[0].homeTeamId='missing','SCORE_TEAM','/body/0/games/0/homeTeamId'),sem('same home and away',n=>n.games[0].awayTeamId='all','SCORE_TEAM','/body/0/games/0/awayTeamId'),sem('leader from a third team',n=>n.games[0].leaders[0].teamId='linen','SCORE_PARTICIPANT','/body/0/games/0/leaders/0/teamId'),sem('soccer event from third team',(n,s)=>s.games[0].events[0].teamId='linen','SCORE_PARTICIPANT','/body/1/games/0/events/0/teamId'),sem('duplicate soccer event',(n,s)=>s.games[0].events[1].id='event1','DUPLICATE_ID','/body/1/games/0/events/1/id'),sem('football possession outside game',(n,s,f)=>f.games[0].possessionTeamId='linen','SCORE_PARTICIPANT','/body/2/games/0/possessionTeamId'),sem('fifth regulation quarter',(n,s,f)=>f.games[0].periods[0].number=5,'FOOTBALL_QUARTER','/body/2/games/0/periods/0/number'),sem('duplicate football period number',(n,s,f)=>{f.games[0].periods[1].kind='quarter';f.games[0].periods[1].number=4;},'FOOTBALL_PERIOD','/body/2/games/0/periods/1/number'),sem('unknown scoring period',(n,s,f)=>f.games[0].events[0].periodId='missing','FOOTBALL_PERIOD','/body/2/games/0/events/0/periodId'),sem('impossible supplied start',n=>n.games[0].startsAt='2027-02-29T12:00Z','SCORE_TIME','/body/0/games/0/startsAt'),sem('unsafe game source',(n,s)=>s.games[0].source={label:'Untrusted',url:'javascript:untrusted()'},'UNSAFE_URL','/body/1/games/0/source/url'),schema('provider endpoint',n=>n.endpoint='https://example.org/provider'),schema('missing explicit score',n=>delete n.games[0].homeScore),schema('fractional score',n=>n.games[0].homeScore=.5),schema('score overflow',n=>n.games[0].homeScore=1000001),schema('soccer minute is not numeric',(n,s)=>s.games[0].events[0].minute=94),schema('football down outside1to4',(n,s,f)=>f.games[0].situation.down=5),schema('timezone-free timestamp',n=>n.games[0].startsAt='2028-02-29T12:00')];return{positives,negatives};}
